function modal(title,body,footer=''){ $('modalHost').innerHTML=`<div class="modal-overlay" id="modalOverlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${E(title)}"><header><h2>${E(title)}</h2><button type="button" class="close" data-action="close" aria-label="Fermer">×</button></header>${body}${footer}</section></div>`;let f=$('modalHost').querySelector('input,select,textarea,button');f?.focus()}
