function download(filename,content,mime='application/json'){const blob=new Blob([content],{type:mime});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function metersToMiles(km){return db.settings.units==='imperial'?`${num(km*.621371,1)} mi`:`${num(km,1)} km`}
function locationBadge(){return `<button type="button" class="btn btn-outline btn-small" data-action="choose-location">⌖ ${locationText()} · Modifier</button>`}
function dailyWeather(weather=ui.weather){let w=weather;if(!w?.hourly?.time)return[];const groups={};w.hourly.time.forEach((t,i)=>{const d=t.slice(0,10);if(!groups[d])groups[d]=[];groups[d].push(makeHour(w,i));});return Object.entries(groups).map(([date,hours])=>({date,hours,peak:hours.filter(h=>h.hour>=6&&h.hour<=21).sort((a,b)=>b.score-a.score)[0]||hours[0],avg:Math.round(hours.reduce((a,x)=>a+x.score,0)/hours.length)}))}
function makeHour(w,i){let h=w.hourly||{},t=h.time?.[i]||'',hour=Number(t.slice(11,13)),rain=DT(h.precipitation_probability?.[i]),wind=DT(h.wind_speed_10m?.[i]),temp=DT(h.temperature_2m?.[i]),pressure=DT(h.pressure_msl?.[i]);let date=t.slice(0,10),didx=w.daily?.time?.indexOf(date)??-1;let sunrise=w.daily?.sunrise?.[didx]||'',sunset=w.daily?.sunset?.[didx]||'';let rise=sunrise?Number(sunrise.slice(11,13)):null,set=sunset?Number(sunset.slice(11,13)):null;let bonus=(rise!==null&&Math.abs(hour-rise)<=2)||(set!==null&&Math.abs(hour-set)<=2)?16:0;let score=50+bonus-(wind??18)*.45-(rain??20)*.17+(pressure!==null&&pressure>=1012&&pressure<=1025?4:0);if((wind??0)>=45)score-=20;if((rain??0)>=85)score-=15;return {time:t,date,hour,wind,rain,temp,pressure,score:Math.round(clamp(score,8,89)),label:hour.toString().padStart(2,'0')+'h',sunrise,sunset};}
function risk(){const w=ui.weather;let h=w?.current||{};const wind=DT(h.wind_speed_10m),prec=DT(h.precipitation),wave=DT(ui.marine?.current?.wave_height);let labels=[];if(wind!==null&&wind>=45)labels.push('Vent fort');if(prec!==null&&prec>=5)labels.push('Précipitations marquées');if(db.location.env==='sea'&&wave!==null&&wave>=2)labels.push('Houle significative');return labels;}
function obsReliability(){if(!ui.weather)return 'Données non disponibles';return new Date()-ui.weatherUpdated>4*60*60*1000?'Prévision en cache · actualisation nécessaire':'Modèle météo · source Open-Meteo'}
function tipByEnv(){return db.location.env==='sea'?'Inspecter les courants et l’état de la mer avant le départ. Le niveau marin modélisé ne constitue pas une table de marée officielle.':'Rechercher les obstacles, les veines de courant et les variations de niveau. La température de l’eau douce n’est pas déduite de celle de l’air.'}
function cover(list,title,max=4){return arr(list).slice(0,max).map(x=>`<div class="item"><div class="item-main"><b>${E(x.name)}</b><small>${E(x.detail||'')}</small></div></div>`).join('')||empty(title)}
async function fetchJSON(url,timeout=11000){const ctrl=new AbortController();const timer=setTimeout(()=>ctrl.abort(),timeout);try{const response=await fetch(url,{signal:ctrl.signal});if(!response.ok)throw new Error('HTTP '+response.status);const x=await response.json();if(x.error)throw new Error(x.reason||'API');return x}finally{clearTimeout(timer)}}
function locationParams(){return `latitude=${encodeURIComponent(db.location.lat)}&longitude=${encodeURIComponent(db.location.lon)}&timezone=auto`}
async function getWeather(force=false){let lat=DT(db.location.lat),lon=DT(db.location.lon);if(lat===null||lon===null)return;let cacheKey='fishora_forecast_'+lat.toFixed(2)+'_'+lon.toFixed(2)+'_'+db.location.env;let stored=null;try{stored=JSON.parse(localStorage.getItem(cacheKey))}catch{}if(!force&&stored&&Date.now()-stored.time<75*60*1000){ui.weather=stored.weather;ui.marine=stored.marine;ui.weatherUpdated=stored.time;ui.weatherInfo='Cache météo';render();return}if(!navigator.onLine){if(stored){ui.weather=stored.weather;ui.marine=stored.marine;ui.weatherUpdated=stored.time;ui.weatherInfo='Données archivées · hors connexion'}render();return}
ui.apiBusy=true;let p=locationParams();let base=`https://api.open-meteo.com/v1/forecast?${p}&forecast_days=16&hourly=temperature_2m,precipitation_probability,wind_speed_10m,pressure_msl,relative_humidity_2m,cloud_cover&daily=sunrise,sunset,precipitation_sum,wind_speed_10m_max&current=temperature_2m,wind_speed_10m,precipitation,weather_code,pressure_msl`;
try{let w=await fetchJSON(base);let marine=null;if(db.location.env==='sea'){try{marine=await fetchJSON(`https://marine-api.open-meteo.com/v1/marine?${p}&forecast_days=7&hourly=wave_height,wave_period,sea_surface_temperature,sea_level_height_msl,ocean_current_velocity&current=wave_height,sea_surface_temperature,ocean_current_velocity`)}catch(e){console.warn('Marine API:',e)}}ui.weather=w;ui.marine=marine;ui.weatherUpdated=Date.now();ui.weatherInfo='Prévisions Open-Meteo actualisées';try{localStorage.setItem(cacheKey,JSON.stringify({time:Date.now(),weather:w,marine}))}catch{}}catch(e){ui.weatherInfo='Prévisions indisponibles : '+e.message;if(stored){ui.weather=stored.weather;ui.marine=stored.marine;ui.weatherUpdated=stored.time;}else{ui.weather=null;ui.marine=null;}toast('Prévisions indisponibles : vérifiez le réseau ou le service.')}finally{ui.apiBusy=false;render()}}
const hourRisk=h=>h.wind!==null&&h.wind>=45||h.rain!==null&&h.rain>85;
function forecastHint(){if(!ui.weather)return 'Activez le réseau ou choisissez un autre lieu pour charger des prévisions.';let today=dailyWeather()[0];if(!today)return'Prévisions indisponibles';return `Fenêtre indicative ${today.peak.label} · indice météo heuristique ${today.peak.score}/100. Ce score n’est pas une probabilité de capture.`}
